-- New slogans and search keywords (approved 2026-11-23).
-- Each UPDATE only replaces the text that was there before, so anything already edited in the admin panel is kept.

-- Store slogan (footer, link card) and the homepage title/description for Google.
UPDATE "Settings" SET "tagline" = 'Твій стиль. Твій ритм.'
WHERE "tagline" IS NULL OR "tagline" = 'Одяг для руху та щоденного життя';

UPDATE "Settings" SET "seoTitle" = 'VELLA — жіночий одяг, взуття та сумки | Інтернет-магазин'
WHERE "seoTitle" IS NULL OR "seoTitle" = 'VELLA — сучасний activewear та базовий гардероб';

UPDATE "Settings" SET "seoDescription" = 'Сучасний жіночий одяг, взуття та аксесуари: пуховики, светри, джинси, шкіряні сумки. Доставка Новою Поштою по Україні, обмін 14 днів.'
WHERE "seoDescription" IS NULL OR "seoDescription" LIKE 'Мінімалістичний одяг для тренувань%';

-- Homepage section headings.
UPDATE "HomepageSection" SET "title" = 'Нове цього сезону', "subtitle" = 'Свіжі надходження, які розбирають першими'
WHERE "title" = 'Новинки та тренди';
UPDATE "HomepageSection" SET "title" = 'Обирай за настроєм' WHERE "title" = 'Категорії';
UPDATE "HomepageSection" SET "title" = 'Щойно в магазині' WHERE "title" = 'Нові надходження';

-- Announcement bar.
UPDATE "Banner" SET "title" = 'Доставка безкоштовно від 2000 ₴' WHERE "title" = 'Безкоштовна доставка від 2000 ₴';
UPDATE "Banner" SET "title" = '−10% на перше замовлення · код WELCOME10' WHERE "title" = '−10% на перше замовлення з кодом WELCOME10';
UPDATE "Banner" SET "title" = '14 днів на обмін і повернення' WHERE "title" = 'Обмін та повернення протягом 14 днів';

